mapper.select:
SELECT COUNT(*)
FROM team_analyses ta JOIN analyses a ON a.id = ta.analysis_id AND a.deleted_at IS NULL
WHERE ta.team_id = #{teamId}

mapper.delete:
DELETE ta FROM team_analyses ta
JOIN analyses a ON a.id = ta.analysis_id
WHERE ta.team_id = #{teamId} AND a.user_id = #{userId}

DELETE ta FROM team_analyses ta
JOIN analyses a ON a.id = ta.analysis_id
WHERE a.user_id = #{userId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM team_analyses ta
    JOIN team_members tm ON tm.team_id = ta.team_id AND tm.user_id = #{userId}
    JOIN analyses a ON a.id = ta.analysis_id AND a.deleted_at IS NULL
    WHERE ta.analysis_id = #{analysisId}
)
